export function listeningTranscriptWithFurigana(text: string) {
	return text
		.split("\n")
		.map((line) => {
			const leading = line.match(/^\s*/)?.[0] || "";
			const trailing = line.match(/\s*$/)?.[0] || "";
			const source = line.slice(leading.length, line.length - trailing.length || undefined);
			return `${leading}${listeningN3FuriganaByLine[source] || source}${trailing}`;
		})
		.join("\n");
}
